#!/usr/bin/env bash
# Golden transcripts for the Rust chat (stage 5), from the OLD app's fold.
#
#   bash rust/fixtures/tools/capture-chat.sh
#
# 1. rust/fixtures/chat/streams/: the recorded CLI streams of desk-app
#    (src/claude/testdata, copied so a later edit there cannot silently move
#    the reference) + three made by desk-bench's fake-claude, with the machine's
#    cwd replaced by a fixed one. The 10 000-line stream is generated by
#    chat-fold.ts itself and not committed.
# 2. rust/fixtures/chat/expected/<case>.json: chat/chat-fold.ts run over them
#    (see its header for what is executed and what is transcribed).
set -euo pipefail
cd "$(dirname "$0")/../../.."
ROOT=$PWD
CHAT=rust/fixtures/chat
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
[ -x node_modules/.bin/esbuild ] || { echo "node_modules missing: ELECTRON_SKIP_BINARY_DOWNLOAD=1 npm ci --ignore-scripts" >&2; exit 1; }

echo "== streams"
mkdir -p $CHAT/streams
cp rust/crates/desk-app/src/claude/testdata/*.jsonl $CHAT/streams/
: > $CHAT/streams/empty.jsonl
(cd rust && cargo build -q -p desk-bench --bin fake-claude)
FC=rust/target/debug/fake-claude
fake() { # <out> <args…>: one turn, the cwd of this machine replaced
  local out=$1; shift
  (cd "$TMP" && "$ROOT/$FC" "$@" || true) 2>/dev/null \
    | sed -E 's#"cwd":"[^"]*"#"cwd":"C:\\\\Users\\\\T\\\\Documents\\\\Strategy Desk"#' > "$CHAT/streams/$out"
}
fake fake_tools.jsonl --events 80 --seed 1 --tool-every 1
fake fake_garbage.jsonl --events 40 --seed 2 --garbage-every 5
fake fake_die.jsonl --events 40 --seed 3 --die-after 15
cat > $CHAT/streams/SOURCES.md <<'EOF'
# Recorded and generated CLI streams

| File | From |
| --- | --- |
| `text_turn.jsonl`, `tool_turn.jsonl`, `interrupted.jsonl`, `auth_error.jsonl`, `resume_missing.jsonl` | copies of `rust/crates/desk-app/src/claude/testdata/` (recorded from claude 2.1.332, anonymised by desk-app) |
| `fake_tools.jsonl` | `fake-claude --events 80 --seed 1 --tool-every 1` |
| `fake_garbage.jsonl` | `fake-claude --events 40 --seed 2 --garbage-every 5` |
| `fake_die.jsonl` | `fake-claude --events 40 --seed 3 --die-after 15` (ends in half a line; the real process exits with code 3) |
| `empty.jsonl` | nothing: a process that dies before its first line |

The `cwd` field of fake-claude's init line is replaced by `C:\Users\T\Documents\Strategy Desk`.
Regenerate with `bash rust/fixtures/tools/capture-chat.sh`.
EOF

echo "== old fold"
node rust/fixtures/tools/chat/build.mjs "$TMP/chat-fold.cjs"
rm -rf $CHAT/expected
CHAT_FOLD_REPO=$ROOT CHAT_FOLD_VAULT=$ROOT/rust/fixtures/golden/vault node "$TMP/chat-fold.cjs" "$ROOT" $CHAT/expected
if grep -rIl -E '/home/|avitr|michael|vitryk' $CHAT; then echo "machine path or personal data in the chat fixtures" >&2; exit 1; fi
echo "done: $(ls $CHAT/expected | wc -l) cases"
